31		var request configPublishRequest
32		if err := decodeSingleJSON(r, &request); err != nil {
33			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
34			return
35		}
36		requestID := strings.TrimSpace(request.RequestID)
37		if requestID == "" {
38			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "requestId is required"})
39			return
40		}
41		if request.BaseVersion == nil {
42			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "baseVersion is required"})
43			return
44		}
45		if *request.BaseVersion < 0 {
46			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "baseVersion must be a non-negative integer"})
47			return
48		}
49		content, ok := nonEmptyJSONObject(w, request.Config)
50		if !ok {
51			return
52		}
53	
54		result, repeat, err := h.store.PublishConfig(r.PathValue("id"), requestID, *request.BaseVersion, content)
55		if errors.Is(err, ErrDeviceNotFound) {
56			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
57			return
58		}
59		if errors.Is(err, ErrConfigConflict) {
60			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
61			return
62		}
63		if errors.Is(err, ErrStorageUnavailable) {
64			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
65			return
66		}
67		if err != nil {
68			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
69			return
70		}
71		status := http.StatusCreated
72		if repeat {
73			status = http.StatusOK
74		}
75		writeJSON(w, status, result)
76	}
