376			if !ok || len(av) != len(bv) {
377				return false
378			}
379			for key, value := range av {
380				other, ok := bv[key]
381				if !ok || !jsonValueEqual(value, other) {
382					return false
383				}
384			}
385			return true
386		case []any:
387			bv, ok := b.([]any)
388			if !ok || len(av) != len(bv) {
389				return false
390			}
391			for i := range av {
