397		case json.Number:
398			// Numbers compare by exact decimal value: 1, 1.0 and 1e0 are equal,
399			// but 9007199254740992 and 9007199254740993 (or 0 and 1e-400) are
400			// not, even though each pair shares one float64.
401			bv, ok := b.(json.Number)
402			return ok && sameJSONNumber(av, bv)
403		case string:
