1	package fleet
2	
3	import (
4		"net/http"
5		"testing"
6	)
7	
8	// --- restart restores the whole configuration state --------------------------
9	
10	func TestPersistentRestartRestoresConfigState(t *testing.T) {
11		dir := t.TempDir()
12		store := openPersistent(t, dir)
13		h := NewHandler(store)
14		mustRegister(t, h, "gw")
15	
16		publishConfig(t, h, "gw", publishBody("r1", 0, `{"v":1}`), http.StatusCreated)
17		publishConfig(t, h, "gw", publishBody("r2", 1, `{"nested":{"a":[1,2,3]}}`), http.StatusCreated)
18		// v2 fails to apply while v1 succeeds later: applied=1, target=2, and the
19		// v2 failure reason must remain visible.
20		postReceipt(t, h, "gw", receiptBody("rc-fail", 2, false, "disk full"), http.StatusCreated)
21		postReceipt(t, h, "gw", receiptBody("rc-ok-1", 1, true, ""), http.StatusCreated)
22		if err := store.Close(); err != nil {
23			t.Fatal(err)
24		}
25	
26		store2 := reopenPersistent(t, dir)
27		h2 := NewHandler(store2)
28	
29		status := getConfigStatus(t, h2, "gw")
30		if status.TargetVersion != 2 || status.AppliedVersion != 1 || status.FailureReason != "disk full" {
31			t.Fatalf("status after restart = %+v", status)
32		}
33		// The newer target is still pending and delivered as the latest only.
34		r := doRequest(t, h2, http.MethodGet, "/v1/devices/gw/configs/pending", "")
35		if r.Code != http.StatusOK {
36			t.Fatalf("pending after restart = %d, want 200", r.Code)
37		}
38		pending := decodeBody[configViewResponse](t, r)
39		if pending.Version != 2 || string(pending.Config) != `{"nested":{"a":[1,2,3]}}` {
40			t.Fatalf("pending after restart = %+v", pending)
41		}
42	
43		// Complete history with contents comes back in ascending version order.
44		configs := listConfigs(t, h2, "gw")
45		if len(configs) != 2 ||
46			configs[0].Version != 1 || string(configs[0].Config) != `{"v":1}` ||
47			configs[1].Version != 2 {
48			t.Fatalf("config history after restart = %+v", configs)
49		}
50	
51		// Receipts come back in receive order with their first receive times.
52		before := listConfigReceipts(t, h2, "gw")
53		if len(before) != 2 || before[0].ReceiptID != "rc-fail" || before[1].ReceiptID != "rc-ok-1" {
54			t.Fatalf("receipts after restart = %+v", before)
55		}
56	
57		// Publish dedup survives: the r2 retry is 200 with its first publish time,
58		// not a new version (even though the clock moved on during reopen).
59		r2retry := publishConfig(t, h2, "gw", publishBody("r2", 1, `{"nested": {"a": [1, 2.0, 3.0]}}`), http.StatusOK)
60		if !r2retry.PublishedAt.Equal(configs[1].PublishedAt) {
61			t.Fatalf("publish retry time = %s, want first time %s", r2retry.PublishedAt, configs[1].PublishedAt)
62		}
63		if r := doRequest(t, h2, http.MethodPost, "/v1/devices/gw/configs",
64			publishBody("r2", 1, `{"nested":{"a":[1,2,4]}}`)); r.Code != http.StatusConflict {
65			t.Fatalf("changed content for old requestId = %d, want 409", r.Code)
66		}
67	
68		// Receipt dedup survives too.
69		rcRetry := postReceipt(t, h2, "gw", receiptBody("rc-fail", 2, false, "disk full"), http.StatusOK)
70		if !rcRetry.ReceivedAt.Equal(before[0].ReceivedAt) {
71			t.Fatalf("receipt retry time = %s, want first %s", rcRetry.ReceivedAt, before[0].ReceivedAt)
72		}
73	
74		// Finish applying v2; the failure reason must clear and stay cleared.
