53	func (h *handler) register(w http.ResponseWriter, r *http.Request) {
54		var request struct {
55			ID   string `json:"id"`
56			Site string `json:"site"`
57		}
58		if err := decodeJSON(r, &request); err != nil || strings.TrimSpace(request.ID) == "" {
59			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "id is required"})
60			return
61		}
62		device, created, err := h.store.Register(strings.TrimSpace(request.ID), strings.TrimSpace(request.Site))
63		if errors.Is(err, ErrStorageUnavailable) {
64			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
65			return
66		}
67		if err != nil {
68			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
69			return
70		}
71		status := http.StatusOK
72		if created {
73			status = http.StatusCreated
74		}
75		writeJSON(w, status, device)
76	}
