478	func (h *handler) listAlerts(w http.ResponseWriter, r *http.Request) {
479		query := r.URL.Query()
480		filter := AlertFilter{RuleID: strings.TrimSpace(query.Get("ruleId"))}
481		if raw := strings.TrimSpace(query.Get("status")); raw != "" {
482			if raw != alertStatusActive && raw != alertStatusEnded {
483				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be active or ended"})
484				return
485			}
486			filter.Status = raw
487		}
488		if raw := strings.TrimSpace(query.Get("acknowledged")); raw != "" {
489			switch raw {
490			case "true", "1":
491				v := true
492				filter.Acknowledged = &v
493			case "false", "0":
494				v := false
495				filter.Acknowledged = &v
496			default:
497				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "acknowledged must be true or false"})
498				return
499			}
500		}
501		alerts, err := h.store.ListAlerts(r.PathValue("id"), filter)
502		if errors.Is(err, ErrDeviceNotFound) {
503			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
504			return
505		}
506		if errors.Is(err, ErrRuleNotFound) {
507			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
508			return
509		}
510		if err != nil {
511			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
512			return
513		}
514		writeJSON(w, http.StatusOK, map[string]any{"alerts": alerts})
515	}
516	
517	func (h *handler) ackAlert(w http.ResponseWriter, r *http.Request) {
518		alertID, err := strconv.ParseInt(r.PathValue("alertId"), 10, 64)
519		if err != nil || alertID < 1 {
520			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "alertId must be a positive integer"})
521			return
522		}
523		alert, err := h.store.AckAlert(r.PathValue("id"), alertID)
524		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrAlertNotFound) {
525			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
526			return
527		}
528		if errors.Is(err, ErrStorageUnavailable) {
529			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
530			return
531		}
532		if err != nil {
533			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
534			return
535		}
536		writeJSON(w, http.StatusOK, alert)
537	}
538	
539	func finiteFloat(value float64) bool {
540		return !math.IsNaN(value) && !math.IsInf(value, 0)
541	}
542	
543	func hasBlankKey(values map[string]*float64) bool {
544		for key := range values {
545			if strings.TrimSpace(key) == "" {
546				return true
547			}
548		}
549		return false
550	}
551	
552	// metricValues converts decoded metric values to plain floats. Decoding into
553	// *float64 keeps JSON null distinguishable from a real 0: a null decodes to a
554	// nil pointer and is rejected here instead of being silently stored as 0.
555	// Non-finite numbers are rejected as before.
556	func metricValues(raw map[string]*float64) (map[string]float64, bool) {
557		values := make(map[string]float64, len(raw))
558		for key, value := range raw {
559			if value == nil || !finiteFloat(*value) {
560				return nil, false
561			}
562			values[key] = *value
563		}
564		return values, true
565	}
566	
567	func decodeJSON(r *http.Request, target any) error {
568		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
569		decoder.DisallowUnknownFields()
570		return decoder.Decode(target)
571	}
572	
573	// decodeSingleJSON requires the body to be exactly one JSON value, rejecting
574	// trailing data such as a second JSON object or concatenated documents.
575	func decodeSingleJSON(r *http.Request, target any) error {
576		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
577		decoder.DisallowUnknownFields()
578		if err := decoder.Decode(target); err != nil {
579			return err
580		}
581		var trailing any
582		if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
583			return errors.New("body must contain a single JSON value")
584		}
585		return nil
586	}
587	
588	func writeJSON(w http.ResponseWriter, status int, value any) {
589		w.Header().Set("Content-Type", "application/json")
590		w.WriteHeader(status)
591		_ = json.NewEncoder(w).Encode(value)
592	}
