562		*clock = clock.Add(time.Hour)
563		// Same receiptId + same content retries with 200 and the first time; it
564		// must not be appended again.
565		retry := postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusOK)
566		if !retry.ReceivedAt.Equal(firstReceived) {
567			t.Fatalf("retry receivedAt = %s, want first %s", retry.ReceivedAt, firstReceived)
568		}
569		receipts := listConfigReceipts(t, h, "gw")
570		if len(receipts) != 1 {
571			t.Fatalf("receipts = %d, want 1", len(receipts))
572		}
573	
574		// Same id, different content => 409 in every direction.
575		for _, body := range []string{
576			receiptBody("rc-f", 1, true, ""),
577			receiptBody("rc-f", 1, false, "other"),
578		} {
579			if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs/receipts", body); r.Code != http.StatusConflict {
580				t.Fatalf("changed receipt %s => %d, want 409", body, r.Code)
581			}
582		}
583		if receipts := listConfigReceipts(t, h, "gw"); len(receipts) != 1 {
584			t.Fatalf("409 retries changed receipts: %+v", receipts)
585		}
586	
587		// A different receiptId can report the later success.
588		postReceipt(t, h, "gw", receiptBody("rc-ok", 1, true, ""), http.StatusCreated)
589		// Re-reporting the old failure id still retries as 200 (stored first result)
590		// rather than becoming a new conflict against applied state.
591		postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusOK)
592	}
593	
594	// --- isolation and ordering --------------------------------------------------
595	
596	func TestConfigVersionsAndDedupArePerDevice(t *testing.T) {
597		h := NewHandler(NewStore())
598		mustRegister(t, h, "a")
599		mustRegister(t, h, "b")
600		body := publishBody("shared", 0, `{"v":1}`)
601		publishConfig(t, h, "a", body, http.StatusCreated)
602		publishConfig(t, h, "b", body, http.StatusCreated)
603		if sa, sb := getConfigStatus(t, h, "a"), getConfigStatus(t, h, "b"); sa.TargetVersion != 1 || sb.TargetVersion != 1 {
604			t.Fatalf("statuses = %+v %+v", sa, sb)
605		}
606		// Each device independently applies and keeps its own receipts.
607		postReceipt(t, h, "a", receiptBody("shared-rc", 1, true, ""), http.StatusCreated)
608		postReceipt(t, h, "b", receiptBody("shared-rc", 1, false, "x"), http.StatusCreated)
609		if sa, sb := getConfigStatus(t, h, "a"), getConfigStatus(t, h, "b"); sa.AppliedVersion != 1 || sb.AppliedVersion != 0 {
610			t.Fatalf("cross-device leak: %+v %+v", sa, sb)
611		}
612	}
613	
614	func TestConfigReceiptsListedInReceiveOrder(t *testing.T) {
615		h := NewHandler(NewStore())
616		mustRegister(t, h, "gw")
617		publishConfig(t, h, "gw", publishBody("r1", 0, `{"v":1}`), http.StatusCreated)
618		postReceipt(t, h, "gw", receiptBody("rc-1", 1, false, "a"), http.StatusCreated)
619		postReceipt(t, h, "gw", receiptBody("rc-2", 1, false, "b"), http.StatusCreated)
620		postReceipt(t, h, "gw", receiptBody("rc-3", 1, true, ""), http.StatusCreated)
621		receipts := listConfigReceipts(t, h, "gw")
622		want := []string{"rc-1", "rc-2", "rc-3"}
623		if len(receipts) != 3 {
624			t.Fatalf("receipts = %d, want 3", len(receipts))
625		}
626		for i, id := range want {
627			if receipts[i].ReceiptID != id {
628				t.Fatalf("order[%d] = %s, want %s", i, receipts[i].ReceiptID, id)
629			}
630		}
631	}
632	
633	// --- config operations leave the other subsystems alone ----------------------
634	
635	func TestConfigOperationsDoNotTouchDeviceActivityOrTelemetry(t *testing.T) {
636		store, clock := newClockStore()
637		h := NewHandler(store)
638		mustRegister(t, h, "gw")
639		*clock = clock.Add(2 * time.Hour)
640		telemetryAt := clock.UTC()
641		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":10}`); r.Code != http.StatusAccepted {
642			t.Fatalf("telemetry = %d", r.Code)
643		}
644		beforeEvents := allEvents(t, h, "gw")
645		if len(beforeEvents) != 1 {
646			t.Fatalf("seed events = %d", len(beforeEvents))
647		}
648	
649		*clock = clock.Add(48 * time.Hour)
650		publishConfig(t, h, "gw", publishBody("r1", 0, `{"v":1}`), http.StatusCreated)
651		getPending(t, h, "gw")
652		postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusCreated)
653		publishConfig(t, h, "gw", publishBody("r2", 1, `{"v":2}`), http.StatusCreated)
654		postReceipt(t, h, "gw", receiptBody("rc-ok", 2, true, ""), http.StatusCreated)
655	
656		snapshot := decodeBody[struct {
657			Devices []Device `json:"devices"`
658		}](t, doRequest(t, h, http.MethodGet, "/v1/fleet", ""))
659		if got := snapshot.Devices[0]; !got.LastSeenAt.Equal(telemetryAt) {
660			t.Fatalf("lastSeenAt = %s, want telemetry time %s (config ops must not refresh it)", got.LastSeenAt, telemetryAt)
661		}
662		events := allEvents(t, h, "gw")
663		if len(events) != 1 {
664			t.Fatalf("telemetry history changed: %+v", events)
665		}
666	}
