	postReceipt(t, h, "gw", receiptBody("rc-3", 1, true, ""), http.StatusCreated)
	receipts := listConfigReceipts(t, h, "gw")
	want := []string{"rc-1", "rc-2", "rc-3"}
	if len(receipts) != 3 {
